async function loadChunkedData(){
 const configResponse=await fetch('./city-config.json').catch(()=>null),config=configResponse?.ok?await configResponse.json().catch(()=>null):null;if(typeof config?.base==='string')cityBaseURL=new URL(config.base,location.href);
 const cityResponse=await fetch(new URL('manifest.json',cityBaseURL)).catch(()=>null);
 const cityCandidate=cityResponse?.ok?parseCityManifest(await cityResponse.text().catch(()=>'')):null;
 if(cityCandidate){cityManifest=cityCandidate;cityManifest.edges=cityManifest.network.edgeCount;return [cityManifest,{nodes:[],edges:[]},{buildings:[],trees:[]}];}
 const response=await fetch('./data/manifest.json');if(!response.ok)throw Error('manifest');const manifest=await response.json();
 const load=async files=>(await Promise.all(files.map(async file=>{const r=await fetch('./data/'+file);if(!r.ok)throw Error(file);return r.json();}))).flat();
 const [metaResponse,nodes,edges,buildings,trees]=await Promise.all([fetch('./data/'+manifest.meta),load(manifest.nodes),load(manifest.edges),load(manifest.buildings),load(manifest.trees)]);
 if(!metaResponse.ok)throw Error(manifest.meta);return [await metaResponse.json(),{nodes,edges},{buildings,trees}];
}
function berlinParts(d){return Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));}
function dateNow(){const p=berlinParts(new Date());return `${p.year}-${p.month}-${p.day}`;}
function selectedISO(){const day=$('date').value,mins=+$('time').value;let ms=Date.parse(day+'T00:00:00Z')+mins*60000;
 // Resolve a Berlin wall clock against the actual IANA DST offset.
 for(let i=0;i<3;i++){const p=berlinParts(new Date(ms)),asUTC=Date.parse(`${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:00Z`),target=Date.parse(day+'T00:00:00Z')+mins*60000;const change=target-asUTC;ms+=change;if(!change)break;}return new Date(ms).toISOString();}
function selectedWeather(){return weatherAt(weatherModel,$('date').value,+$('time').value);}
function effectiveWeather(){return liveWeatherEnabled?selectedWeather():null;}
function localTimeLabel(value){if(!value)return '–';const [day,time]=value.split('T');return `${day.split('-').reverse().join('.')} · ${time||''}`;}
function weatherCondition(group){const key='weather'+group[0].toUpperCase()+group.slice(1),icons={clear:'☀',partlyCloudy:'🌤',overcast:'☁',fog:'≋',drizzle:'🌦',rain:'🌧',snow:'❄',thunderstorm:'⚡',unknown:'◌'};return {label:t(key),icon:icons[group]||icons.unknown};}
function updateWeatherOpacity(weather=effectiveWeather()){
 if(!map?.getLayer?.('shade-fill'))return;const weight=weather?.solarWeight;
 map.setPaintProperty('shade-fill','raster-opacity',displayShadowOpacity(weight,currentSun?.altitude));
}

function renderWeather(force=false){
 const strip=$('weather-strip');if(!strip)return;const key=`${lang}|${weatherState}|${weatherIsStale}|${weatherModel?.retrievedAt}|${liveWeatherEnabled}|${$('date').value}|${Math.round((+$('time').value||0)/60)}`;if(!force&&key===lastWeatherRenderKey)return;lastWeatherRenderKey=key;
 const weather=selectedWeather();strip.dataset.state=weather?'ready':weatherState;strip.dataset.mode=liveWeatherEnabled?'live':'model';const toggle=$('weather-toggle');
 if(toggle){toggle.textContent=t(liveWeatherEnabled?'weatherLive':'weatherClearSky');toggle.title=t(liveWeatherEnabled?'weatherToggleOn':'weatherToggleOff');toggle.setAttribute('aria-label',toggle.title);toggle.setAttribute('aria-pressed',String(liveWeatherEnabled));}
 if(!weather){$('weather-icon').textContent='◌';$('weather-temperature').textContent='–';$('weather-condition').textContent=t(weatherState==='loading'?'weatherLoading':weatherModel?'weatherOutside':'weatherRetry');for(const id of ['weather-cloud','weather-radiation','weather-wind'])$(id).textContent='–';$('weather-details').textContent=t('weatherFallback');updateWeatherOpacity(null);return;}
 const condition=weatherCondition(weatherCodeGroup(weather.weatherCode));$('weather-icon').textContent=condition.icon;$('weather-temperature').textContent=`${Math.round(weather.temperature)}°`;$('weather-condition').textContent=condition.label+(weatherIsStale?' · '+(lang==='de'?'gespeichert':'cached'):'');
 $('weather-cloud').textContent=Number.isFinite(weather.cloudCover)?`${Math.round(weather.cloudCover)} %`:'–';$('weather-radiation').textContent=Number.isFinite(weather.directRadiation)?`${Math.round(weather.directRadiation)} W/m²`:'–';$('weather-wind').textContent=Number.isFinite(weather.windSpeed)?`${Math.round(weather.windSpeed)} km/h`:'–';$('weather-wind-arrow').style.transform=`rotate(${(weather.windDirection||0)+180}deg)`;
 const retrieved=new Intl.DateTimeFormat(lang==='de'?'de-DE':'en-GB',{timeZone:'Europe/Berlin',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(weatherModel.retrievedAt)),valid=weather.time.slice(11,16),source=weatherModel.source||'Open-Meteo',detail=$('weather-details');
 detail.textContent=`${lang==='de'?'Vorhersage':'Forecast'} ${valid} · ${t('weatherRetrieved')} ${retrieved} · ${source}${weatherIsStale?' · '+t('weatherStale'):''}${weather.radiationEstimated?' · '+(lang==='de'?'Sonnenwirkung aus Wolkenanteil':'Sun effect estimated from clouds'):''} · CC BY 4.0`;
 detail.title=t('weatherModel');updateWeatherOpacity(liveWeatherEnabled?weather:null);
}

async function loadWeather(){
 if(weatherLoadingPromise)return weatherLoadingPromise;
 const run=async()=>{let cached=null;try{cached=JSON.parse(localStorage.getItem(WEATHER_CACHE_KEY)||'null');if(!cached){const legacy=JSON.parse(localStorage.getItem('sonnenpfad.weather.stuttgart.v1')||'null');if(legacy?.payload)cached=normalizeWeather(legacy.payload,legacy.retrievedAt);}}catch{}
  if(usableWeatherCache(cached)){weatherModel=cached;weatherIsStale=Boolean(cached.stale)||Date.now()-cached.retrievedAt>=WEATHER_CACHE_MS;weatherState='ready';renderWeather(true);if(!weatherIsStale)return;}
  if(!weatherModel){weatherState='loading';renderWeather();}
  try{const model=await requestWeatherModel({baseURL:location.href});weatherModel=model;weatherIsStale=Boolean(model.stale)||Date.now()-model.retrievedAt>=WEATHER_CACHE_MS;weatherState='ready';try{localStorage.setItem(WEATHER_CACHE_KEY,JSON.stringify(model));}catch{}renderWeather(true);if(!exploreMode&&(result||serverRoutingPending)&&preference!=='balanced')calculate();}
  catch(error){weatherState=weatherModel?'ready':'retry';weatherIsStale=Boolean(weatherModel);renderWeather(true);console.warn('Weather refresh postponed:',error);}
 };
 weatherLoadingPromise=run().finally(()=>{weatherLoadingPromise=null;clearTimeout(weatherRefreshTimer);weatherRefreshTimer=setTimeout(()=>{if(!document.hidden)loadWeather();},weatherState==='retry'||weatherIsStale?60000:WEATHER_CACHE_MS);});return weatherLoadingPromise;
}

function clientSunPosition(date,lat=48.777,lon=9.18){const rad=Math.PI/180,jd=date.getTime()/86400000+2440587.5,n=jd-2451545,L=(280.46+.9856474*n)%360,g=(357.528+.9856003*n)*rad,lambda=(L+1.915*Math.sin(g)+.020*Math.sin(2*g))*rad,eps=(23.439-.0000004*n)*rad,ra=Math.atan2(Math.cos(eps)*Math.sin(lambda),Math.cos(lambda)),dec=Math.asin(Math.sin(eps)*Math.sin(lambda)),gmst=(280.46061837+360.98564736629*n)*rad,H=gmst+lon*rad-ra,phi=lat*rad,altitude=Math.asin(Math.sin(phi)*Math.sin(dec)+Math.cos(phi)*Math.cos(dec)*Math.cos(H)),azimuth=(Math.atan2(Math.sin(H),Math.cos(H)*Math.sin(phi)-Math.tan(dec)*Math.cos(phi))+Math.PI+2*Math.PI)%(2*Math.PI);return {altitude:altitude/rad,azimuth:azimuth/rad};}
function updateImmediateSun(){const center=map?.getCenter?.(),lon=center?.lng??9.18,lat=center?.lat??48.777;currentSun=clientSunPosition(new Date(selectedISO()),lat,lon);updateClock();}
function aboutContent(){return lang==='de'?`<p><strong>Sonnenpfad</strong> wurde von <strong>Mohammadreza Bakhshi</strong> entwickelt und nutzt Daten des <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Fußgängeratlas Stuttgart</a>.</p><ul><li><strong>Gebiet:</strong> ${cityManifest?'Stadtgebiet Stuttgart':'Zentrum Stuttgart'}. ${meta?meta.edges.toLocaleString('de-DE'):'–'} Teilkanten aus dem bereinigten Netz; Datensatz vom 15.09.2026.</li><li><strong>Themen:</strong> Steigung, Oberfläche, Sommer-/Winterschatten, UTCI, Lärm und relative Windexposition stammen aus dem Atlas. UTCI und Wind sind modellierte Indikatoren, keine Live-Messwerte.</li><li><strong>Mobilitätsprofile:</strong> Bekannte harte Hindernisse werden ausgeschlossen; fehlende Angaben bleiben routbar und werden im Ergebnis als Unsicherheit ausgewiesen. Ein Profil ist keine Barrierefreiheits-Zertifizierung und ersetzt keine Prüfung vor Ort.</li><li><strong>3D-Darstellung:</strong> Gebäude aus OpenStreetMap/OpenFreeMap und geschlossene Baumkronen auf einem statischen, geglätteten Anzeigegelände aus Atlas-Netzhöhen. Atlas-Höhen und Steigungen bleiben unabhängig davon für Routenberechnungen erhalten.</li><li><strong>Schatten:</strong> Sonnenstand, Gebäudehöhen und vereinfachte Baumkronen. Die Berechnung nimmt eine horizontale Bodenfläche an; Geländeverschattung, Fassadenrückstrahlung und Wolken werden nicht modelliert.</li><li><strong>Wege:</strong> Punkte werden automatisch mit einer nahegelegenen, gemeinsam erreichbaren Komponente des Fußwegenetzes verbunden. Kurze Anschlusslinien zählen nicht zur Weglänge.</li><li><strong>Datenschutz:</strong> Für „Direkt“ im Standardprofil werden Start- und Zielkoordinaten an den Sonnenpfad-Server übertragen. Andere Profile werden derzeit im Browser berechnet. Geteilte Links enthalten gewählte Koordinaten und Karteneinstellungen.</li></ul><p>Grundkarte: <a href="https://openfreemap.org/" target="_blank" rel="noreferrer">OpenFreeMap</a> / OpenMapTiles / <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>.</p>`:`<p><strong>Sonnenpfad</strong> was developed by <strong>Mohammadreza Bakhshi</strong> and uses data from the <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Stuttgart Pedestrian Atlas</a>.</p><ul><li><strong>Coverage:</strong> ${cityManifest?'Stuttgart city area':'central Stuttgart'}. ${meta?meta.edges.toLocaleString('en-GB'):'–'} subedges from the cleaned network, dataset dated 15 September 2026.</li><li><strong>Themes:</strong> slope, surface, summer/winter shade, UTCI, noise and relative wind exposure come from the atlas. UTCI and wind are modelled indicators, not live measurements.</li><li><strong>Mobility profiles:</strong> Known hard barriers are excluded; missing attributes remain routable and are reported as uncertainty. A profile is not an accessibility certification and does not replace an on-site check.</li><li><strong>3D display:</strong> OpenStreetMap/OpenFreeMap buildings and closed tree crowns on static smoothed display terrain reconstructed from Atlas network heights. Atlas elevations and gradients remain separate for route calculations.</li><li><strong>Shade:</strong> solar position, building heights and simplified tree crowns. The calculation assumes flat ground and does not include terrain occlusion, clouds or reflected radiation.</li><li><strong>Routes:</strong> points connect to a nearby mutually reachable component. Short access lines are excluded from route length.</li><li><strong>Privacy:</strong> For Direct with the standard profile, start and destination coordinates are sent to the Sonnenpfad server. Other profiles are currently calculated in the browser. Shared links contain selected coordinates and map settings.</li></ul><p>Basemap: <a href="https://openfreemap.org/" target="_blank" rel="noreferrer">OpenFreeMap</a> / OpenMapTiles / <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>.</p>`;}
aboutContent=()=>lang==='de'?`<p><strong>Sonnenpfad</strong> wurde von <strong>Mohammadreza Bakhshi</strong> entwickelt und nutzt Daten des <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Fußgängeratlas Stuttgart</a>.</p><ul><li><strong>Live-Wetter:</strong> stündliche Modellvorhersage von Open-Meteo für einen festen Referenzpunkt im Zentrum Stuttgarts. Bei Ausfällen liefert MET Norway eine Ersatzvorhersage. Gültigkeits- und Abrufzeit sind sichtbar; es handelt sich nicht um eine Stationsmessung.</li><li><strong>Wolken & Strahlung:</strong> Die geometrischen Schattenflächen bleiben ein Klarhimmelmodell. Direkte Strahlung schwächt jedoch Darstellung und Routenpräferenz automatisch ab. Bei fehlenden Wetterdaten bleibt das bisherige Klarhimmelmodell aktiv.</li><li><strong>Wind:</strong> Die Wetterleiste zeigt Wind in 10 m Höhe. Das Karten-Linienthema zeigt weiterhin die relative Atlas-Windexposition und keine Live-Mikroströmung.</li><li><strong>Mobilität:</strong> Bekannte harte Hindernisse werden ausgeschlossen; fehlende Atlasangaben bleiben routbar und als Unsicherheit sichtbar. Das Ergebnis ist keine Barrierefreiheits-Zertifizierung.</li><li><strong>Datenschutz:</strong> Für „Direkt“ im Standardprofil werden Start- und Zielkoordinaten an den Sonnenpfad-Server übertragen. Andere Profile werden derzeit im Browser berechnet. Open-Meteo erhält nur die feste Stuttgart-Koordinate sowie übliche Anfrage-Metadaten, nicht Start, Ziel oder Gerätestandort.</li></ul><p>Quelle Wetter: <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a>, Wetterdaten CC BY 4.0. Modell, Geometrie und Zustand vor Ort können abweichen.</p>`:`<p><strong>Sonnenpfad</strong> was developed by <strong>Mohammadreza Bakhshi</strong> and uses data from the <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Stuttgart Pedestrian Atlas</a>.</p><ul><li><strong>Live weather:</strong> hourly Open-Meteo model forecast for a fixed reference point in central Stuttgart. MET Norway supplies fallback forecasts. Validity and retrieval time are shown; this is not a station observation.</li><li><strong>Clouds & radiation:</strong> Geometric shadow areas remain a clear-sky model. Direct radiation automatically weakens their display and the routing preference. If weather is unavailable, the previous clear-sky model remains active.</li><li><strong>Wind:</strong> The weather bar shows 10 m wind. The map line theme still represents relative atlas wind exposure, not live street-level flow.</li><li><strong>Mobility:</strong> Known hard barriers are excluded; missing atlas attributes stay routable and visible as uncertainty. This is not an accessibility certification.</li><li><strong>Privacy:</strong> For Direct with the standard profile, start and destination coordinates are sent to the Sonnenpfad server. Other profiles are currently calculated in the browser. Open-Meteo receives only the fixed Stuttgart coordinate and ordinary request metadata, not the route endpoints or device location.</li></ul><p>Weather source: <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a>, weather data CC BY 4.0. Forecast, geometry and on-site conditions can differ.</p>`;
const step6About=()=>lang==='de'?`<p><strong>Sonnenpfad</strong> wurde von <strong>Mohammadreza Bakhshi</strong> entwickelt und nutzt Daten des <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Fußgängeratlas Stuttgart</a>.</p><ul><li><strong>Live-Wetter:</strong> Die direkte Strahlung regelt stufenlos, wie stark Sonne und Schatten die Route beeinflussen. Unter 40 W/m² werden keine Schattenumwege erzeugt; ohne passende Wetterdaten gilt transparent das geometrische Klarhimmelmodell.</li><li><strong>Mobilität:</strong> Das gewählte Profil wird zuerst strikt angewendet. Gibt es so keine Verbindung, lockert die App Kriterien stufenweise und kennzeichnet die bestmögliche Route deutlich. Treppen werden zuletzt freigegeben. Das Ergebnis ist keine Barrierefreiheits-Zertifizierung.</li><li><strong>Darstellung:</strong> Treppenlinien stammen aus <code>steps=yes</code>. POIs werden bei Kollision nicht ausgeblendet. Das Luftbild ist das amtliche DOP20 des LGL Baden-Württemberg.</li><li><strong>Datenschutz:</strong> Für „Direkt“ im Standardprofil werden Start- und Zielkoordinaten an den Sonnenpfad-Server übertragen. Andere Profile werden derzeit im Browser berechnet. Open-Meteo erhält nur die feste Stuttgart-Koordinate, nicht Start, Ziel oder Gerätestandort.</li></ul><p>Wetter: <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a> / <a href="https://www.met.no/" target="_blank" rel="noreferrer">MET Norway</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Bei MET Norway wird die Sonnenwirkung aus dem Wolkenanteil geschätzt. Luftbild: LGL-BW (2026), Datenlizenz Deutschland – Namensnennung – Version 2.0, <a href="https://www.lgl-bw.de/" target="_blank" rel="noreferrer">www.lgl-bw.de</a>.</p>`:`<p><strong>Sonnenpfad</strong> was developed by <strong>Mohammadreza Bakhshi</strong> and uses data from the <a href="https://github.com/Reza-Bakhshi7/fussgaengeratlas-stuttgart" target="_blank" rel="noreferrer">Stuttgart Pedestrian Atlas</a>.</p><ul><li><strong>Live weather:</strong> Direct radiation continuously controls the influence of sun and shade on routing. Below 40 W/m² no shade detour is made; without matching weather data the geometric clear-sky model is used transparently.</li><li><strong>Mobility:</strong> The selected profile is applied strictly first. If that yields no connection, criteria are relaxed step by step and the best available route is clearly labelled. Stairs are released last. This is not an accessibility certification.</li><li><strong>Display:</strong> Stair lines come from <code>steps=yes</code>. POIs are not hidden by collisions. Aerial imagery is the official DOP20 from LGL Baden-Württemberg.</li><li><strong>Privacy:</strong> For Direct with the standard profile, start and destination coordinates are sent to the Sonnenpfad server. Other profiles are currently calculated in the browser. Open-Meteo receives only the fixed Stuttgart coordinate, not the route endpoints or device location.</li></ul><p>Weather: <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a> / <a href="https://www.met.no/" target="_blank" rel="noreferrer">MET Norway</a> · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. MET Norway sun influence is estimated from cloud cover. Aerial imagery: LGL-BW (2026), Data Licence Germany – Attribution – Version 2.0, <a href="https://www.lgl-bw.de/" target="_blank" rel="noreferrer">www.lgl-bw.de</a>.</p>`;
aboutContent=step6About;
const productionAbout=aboutContent;aboutContent=()=>productionAbout()+(isRoutingPreview(location.hostname)?`<p>${lang==='de'?'Diese Vorschau berechnet auch „Direkt“ mit der vorhandenen Browser-Routingengine. Die Produktivdomain verwendet dafür weiterhin Oracle.':'This preview also calculates Direct with the existing browser routing engine. The production domain continues to use Oracle for Direct.'}</p>`:'');
function language(){featureRequestId++;featurePopup?.remove();featurePopup=null;clearFeatureSelection();updateExperienceLanguage();document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));document.querySelectorAll('[data-i-title]').forEach(el=>el.title=t(el.dataset.iTitle));$('language').textContent=lang==='de'?'EN':'DE';$('language').setAttribute('aria-label',lang==='de'?'Switch to English':'Auf Deutsch wechseln');$('about-content').innerHTML=aboutContent();status(statusKey);for(const [id,k]of [['swap','swap'],['pick-origin','pickOrigin'],['pick-destination','pickDestination'],['locate','locate'],['fit','fit'],['close-about','close']]){const element=$(id);if(element){element.setAttribute('aria-label',t(k));element.title=t(k);}}document.querySelectorAll('[data-profile],[data-slope]').forEach(button=>button.title=button.querySelector('[data-i]').textContent);$('origin').setAttribute('aria-label',t('from'));$('destination').setAttribute('aria-label',t('to'));if($('mobility-profile'))$('profile-description').textContent=profileDescriptions[lang][$('mobility-profile').value]||'';updateStep4Language();if(result)showResult();updateClock();renderWeather(true);}
function themeProperties(values=[],structure=0,edgeId=-1){return {sl:values[0]??-1,su:values[1]??0,ss:values[2]??-1,sw:values[3]??-1,us:values[4]??-999,uw:values[5]??-999,n:values[6]??-1,w:values[7]??-1,st:structure,e:edgeId,steps:edgeId>=0&&stepFlags[edgeId]?1:0};}
function renderThemeLegend(){const box=$('theme-legend'),definition=THEME_DEFS[activeTheme];if(!box||!definition||!exploreMode){if(box)box.hidden=true;return;}box.hidden=false;box.innerHTML=`<strong></strong><div class="legend-items"></div><div class="legend-zoom" hidden></div>`;box.querySelector('strong').textContent=definition[lang];const items=box.querySelector('.legend-items');for(const [color,deLabel,enLabel=deLabel] of definition.legend){const item=document.createElement('span');item.className='legend-item';item.innerHTML='<i class="legend-line"></i><span></span>';item.querySelector('i').style.background=color;item.querySelector('span').textContent=lang==='de'?deLabel:enLabel;items.append(item);}const note=box.querySelector('.legend-zoom');note.textContent=t('layersZoom');note.hidden=!map||map.getZoom()>=14.5;}
function applyTheme({reload=true}={}){
 if(map?.getLayer('network-line')){const definition=THEME_DEFS[activeTheme]||THEME_DEFS.slope;map.setPaintProperty('network-line','line-color',['case',['>', ['get','st'],0],'#aeb8bd',definition.expression]);map.setPaintProperty('network-line','line-width',['interpolate',['linear'],['zoom'],14.5,2,17,3.2,19,4.5]);map.setPaintProperty('network-line','line-opacity',.92);map.setLayoutProperty('network-line','visibility',exploreMode?'visible':'none');for(const id of ['stairs-halo','stairs-treads','slope-arrows'])if(map.getLayer(id))map.setLayoutProperty(id,'visibility',exploreMode&&activeTheme==='slope'?'visible':'none');}
 renderThemeLegend();if(reload&&exploreMode&&ready)loadVisibleCityTiles().catch(console.warn);
}

function updateCrossingLegend(){const box=$('crossing-legend');if(!box)return;box.hidden=!exploreMode||!selectedPois.has(1);if(box.hidden)return;box.replaceChildren();const heading=document.createElement('strong');heading.textContent=lang==='de'?'Ampelqualität im Fußgängeratlas':'Signal-crossing quality in the pedestrian atlas';box.append(heading);for(const quality of [3,2,1,0]){const definition=CROSSING_CLASSES[quality],item=document.createElement('div'),dot=document.createElement('i'),text=document.createElement('span');item.className='crossing-legend-item';dot.style.background=definition.color;text.textContent=`${definition[lang]} · ${definition[lang+'Rule']}`;item.append(dot,text);box.append(item);}const note=document.createElement('small');note.textContent=lang==='de'?'Farbe: Ton, Vibration und taktiles Leitsystem. Rollstuhleignung steht separat im Detailfenster.':'Colour: sound, vibration and tactile paving. Wheelchair suitability is shown separately in the detail popup.';box.append(note);}
function applyPoiFilter({reload=true}={}){if(map?.getLayer('poi-points')){map.setFilter('poi-points',['in',['get','k'],['literal',[...selectedPois]]]);map.setLayoutProperty('poi-points','visibility',exploreMode?'visible':'none');}updateCrossingLegend();if(reload&&exploreMode&&ready)loadVisibleCityTiles().catch(console.warn);}

function updateStep4Language(){if(!$('theme'))return;for(const option of $('theme').options)option.textContent=THEME_DEFS[option.value]?.[lang]||option.textContent;for(const label of document.querySelectorAll('.theme-option')){const definition=THEME_DEFS[label.dataset.theme];if(!definition)continue;label.querySelector('.theme-name').textContent=definition[lang];label.title=definition[lang]+': '+definition[lang+'Help'];label.dataset.tooltip=label.title;label.querySelector('input').setAttribute('aria-label',`${definition[lang]}. ${definition[lang+'Help']}`);}for(const label of document.querySelectorAll('.poi-toggle')){const definition=POI_DEFS.find(item=>item.k===+label.dataset.kind);if(definition){label.querySelector('.poi-name').textContent=definition[lang];label.title=definition[lang];label.dataset.tooltip=definition[lang];label.querySelector('input').setAttribute('aria-label',definition[lang]);}}const layersToggle=$('layers-toggle'),layersTitle=t('layersTitle');layersToggle.title=layersTitle;layersToggle.setAttribute('aria-label',layersTitle);$('theme-description').textContent=THEME_DEFS[activeTheme][lang+'Help'];renderThemeLegend();updateCrossingLegend();}
function refreshPoiControlIcons(){for(const label of document.querySelectorAll('.poi-toggle')){const definition=POI_DEFS.find(item=>item.k===+label.dataset.kind);if(definition&&poiIcons[definition.icon])label.style.setProperty('--poi-icon',`url("${poiIcons[definition.icon]}")`);}}
function setupStep4Controls(){const themes=$('theme-options');for(const [key,definition] of Object.entries(THEME_DEFS)){const label=document.createElement('label');label.className='theme-option';label.dataset.theme=key;label.style.setProperty('--theme-color',definition.legend[0][0]);label.innerHTML=`<input type="radio" name="line-theme" value="${key}"><i></i><span class="theme-name"></span>`;const input=label.querySelector('input');input.checked=key===activeTheme;input.onchange=()=>{if(!input.checked)return;activeTheme=key;$('theme').value=key;document.querySelectorAll('.theme-option').forEach(item=>item.classList.toggle('selected',item.dataset.theme===key));applyTheme();updateStep4Language();};label.onmouseenter=()=>{$('theme-description').textContent=definition[lang+'Help'];};label.onmouseleave=()=>{$('theme-description').textContent=THEME_DEFS[activeTheme][lang+'Help'];};label.classList.toggle('selected',input.checked);themes.append(label);}const holder=$('poi-options');for(const definition of POI_DEFS){const label=document.createElement('label');label.className='poi-toggle';label.dataset.kind=definition.k;label.style.setProperty('--poi-color',definition.color);label.style.setProperty('--poi-foreground',definition.foreground);label.innerHTML=`<input type="checkbox" value="${definition.k}"><span class="poi-symbol"></span><span class="poi-name"></span>`;const input=label.querySelector('input');input.checked=selectedPois.has(definition.k);input.onchange=event=>{event.target.checked?selectedPois.add(definition.k):selectedPois.delete(definition.k);applyPoiFilter();};holder.append(label);}$('theme').value=activeTheme;const close=()=>{$('layers-panel').hidden=true;$('layers-toggle').setAttribute('aria-expanded','false');};$('layers-toggle').onclick=()=>{const opening=$('layers-panel').hidden;$('layers-panel').hidden=!opening;$('layers-toggle').setAttribute('aria-expanded',String(opening));};$('layers-close').onclick=close;refreshPoiControlIcons();updateStep4Language();}
function updateSunDirection(){citySceneLayer?.setSun(currentSun);const el=$('sun-direction');if(!el||!currentSun)return;const angle=currentSun.azimuth-(map?.getBearing()||0);el.style.setProperty('--sun-angle',`${angle}deg`);el.style.setProperty('--ray-angle',`${angle+180}deg`);el.classList.toggle('is-night',currentSun.altitude<=0);el.setAttribute('aria-label',lang==='de'?`Sonne: ${Math.round(currentSun.altitude)} Grad Höhe, ${Math.round(currentSun.azimuth)} Grad Azimut`:`Sun: ${Math.round(currentSun.altitude)} degrees elevation, ${Math.round(currentSun.azimuth)} degrees azimuth`);}
function updateClock(){const v=Math.round(+$('time').value),hours=Math.floor(v/60)%24,minutes=v%60;$('clock').textContent=String(hours).padStart(2,'0')+':'+String(minutes).padStart(2,'0');if(currentSun)$('sun-elevation').textContent=currentSun.altitude<=0?t('night'):currentSun.altitude<=2?t('lowSun'):`☀ ${Math.round(currentSun.altitude)}° · ${t('sunHeight')}`;updateSunDirection();renderWeather();}
function placeLabel(feature){const p=feature.properties||{},name=p.name||p.street||p.city||t('point'),context=[p.street&&p.street!==name?p.street:null,p.housenumber,p.postcode,p.city].filter(Boolean).join(' ');return {name,context};}
function showSearchResults(i,features,message=''){const box=$(i?'destination-results':'origin-results');box.replaceChildren();if(message){const item=document.createElement('div');item.className='search-empty';item.textContent=message;box.append(item);}for(const featureItem of features){const coordinates=featureItem.geometry?.coordinates;if(!Array.isArray(coordinates)||coordinates.length<2)continue;const label=placeLabel(featureItem),button=document.createElement('button');button.type='button';button.className='search-result';button.setAttribute('role','option');button.innerHTML=`<strong></strong><span></span>`;button.querySelector('strong').textContent=label.name;button.querySelector('span').textContent=label.context;button.onclick=()=>{setCustom(i,[coordinates[0],coordinates[1]],[label.name,label.context].filter(Boolean).join(', '));box.hidden=true;if(points.every(Boolean)&&ready&&!exploreMode)calculate();else map?.flyTo({center:coordinates,zoom:15});};box.append(button);}box.hidden=!box.childElementCount;}
