 const line=values.map(([d,z])=>{if(!Number.isFinite(d)||!Number.isFinite(z)){open=false;return '';}
  const command=open?'L':'M';open=true;return command+(d/total*w).toFixed(2)+' '+(6+(high-z)/(high-low)*(h-16)).toFixed(2);}).join(' ');
